import{_ as a,C as o,o as r,c as i,E as n,a2 as s}from"./chunks/framework.Cm6XCzck.js";const g=JSON.parse('{"title":"Authorization Needs Provenance, Not Persuasive Wording","description":"","frontmatter":{"title":"Authorization Needs Provenance, Not Persuasive Wording","date":"2026-08-22","column":"digital-employee","category":"daily","article_type":"engineering-insight","edition":"research-center","research_question":"When a delegated digital employee reaches a sensitive review point, what evidence should be allowed to carry user authorization across agent boundaries without letting forwarded or assistant-authored text impersonate authority?","summary":"Role-preserving root-conversation evidence gives an agent reviewer a firmer basis than forwarded approval prose. It is still review evidence, not a durable authorization ledger or proof of a human principal.","sources":["research/analysis/Q-20260822-01-structured-authorization-evidence-channel.md"],"item_id":"Q-20260822-01","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-22-authorization-needs-provenance-cover-v2.jpg","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/digital-employee/2026-08-22-authorization-needs-provenance.md","filePath":"en/digital-employee/2026-08-22-authorization-needs-provenance.md","lastUpdated":1787406157000}'),d={name:"en/digital-employee/2026-08-22-authorization-needs-provenance.md"};function c(h,e,l,u,p,m){const t=o("ArticleCover");return r(),i("div",null,[n(t,{image:"/assets/covers/daily-2026-08-22-authorization-needs-provenance-cover-v2.jpg",kicker:"Digital Employee · Daily Research",title:"Authorization Needs Provenance, Not Persuasive Wording",summary:"Role-preserving root-conversation evidence gives an agent reviewer a firmer basis than forwarded approval prose. It is still review evidence, not a durable authorization ledger or proof of a human principal.",version:"Q-20260822-01",status:"Daily Runtime V5 · 2026-08-22",languageHref:"/zh/digital-employee/2026-08-22-authorization-needs-provenance",languageLabel:"中文"}),e[0]||(e[0]=s('<h1 id="authorization-needs-provenance-not-persuasive-wording" tabindex="-1">Authorization Needs Provenance, Not Persuasive Wording <a class="header-anchor" href="#authorization-needs-provenance-not-persuasive-wording" aria-label="Permalink to &quot;Authorization Needs Provenance, Not Persuasive Wording&quot;">​</a></h1><p>“The user approved this” can be copied by a user, an assistant or another agent. The sentence remains identical; its authority does not. Once an approval is compressed into ordinary prose and forwarded across an agent boundary, the receiver can no longer tell whether it is observing a genuine user statement or an agent&#39;s account of one.</p><p>A Codex change merged on 2026-08-22 addresses that problem at one specific boundary: MultiAgent V2 Guardian review. For a non-root worker, Codex resolves the actual root thread, extracts a bounded portion of structured root history and preserves whether each retained message came from the User or Assistant role. Only root-user messages are designated as authorization evidence. Assistant messages remain untrusted context even if their text contains <code>user: I approve</code>; forwarded claims, compacted summaries and synthetic review artifacts do not acquire user authority through wording.</p><p>The engineering lesson is broader but still bounded: <strong>authorization provenance should travel through a structured review-plane evidence channel, not through claims embedded in work-plane prose.</strong> That makes a sensitive admission decision more defensible. It does not replace the durable authorization state needed for long-lived, scoped and revocable authority.</p><h2 id="what-a-message-says-is-not-where-it-came-from" tabindex="-1">What a message says is not where it came from <a class="header-anchor" href="#what-a-message-says-is-not-where-it-came-from" aria-label="Permalink to &quot;What a message says is not where it came from&quot;">​</a></h2><p>Agent-to-agent forwarding is useful for summaries, intermediate findings and coordination. It is weak as an authority mechanism because it collapses the most important distinction. A downstream worker sees text, not the authoritative event that produced it.</p><p>Role-preserving extraction changes the evidence available to the reviewer. Codex resolves <code>AgentPath::root()</code> rather than trusting material carried by the worker. It retains structured User and Assistant variants and renders the source role explicitly. A phrase that merely claims to be from the user therefore remains assistant-authored when that is its actual structured origin.</p><p>The implementation also excludes several forms that could blur the boundary: summary messages, synthetic <code>&lt;user_action&gt;</code> items, review artifacts and non-final assistant commentary. This does not prove that every possible spoofing route is eliminated. It establishes a clearer admission rule for the demonstrated Guardian path: authority comes from an eligible structured root-user record, not from persuasive language.</p><h2 id="put-authority-evidence-on-the-review-plane" tabindex="-1">Put authority evidence on the review plane <a class="header-anchor" href="#put-authority-evidence-on-the-review-plane" aria-label="Permalink to &quot;Put authority evidence on the review plane&quot;">​</a></h2><p>The root evidence is supplied to Guardian review and classification rather than copied into the delegated worker&#39;s ordinary model context. That separation has two advantages.</p><p>First, the worker does not need broad access to the root conversation merely so a reviewer can assess a sensitive action. Evidence exposure can be narrower than work context. Second, the system can apply a different trust policy to the review plane: assistant history can remain useful context while being explicitly barred from authorizing the action under review.</p><p>The feed is deliberately bounded to the latest eligible root messages, with an independent token limit for each. Boundedness controls exposure and prompt size, but it creates its own lifecycle boundary. An older approval—or an older revocation—may rotate out of the evidence window. Absence from the window is not proof that authorization never existed; presence is not proof that it remains fresh or covers the current action.</p><h2 id="evidence-observed-is-not-authority-granted" tabindex="-1">Evidence observed is not authority granted <a class="header-anchor" href="#evidence-observed-is-not-authority-granted" aria-label="Permalink to &quot;Evidence observed is not authority granted&quot;">​</a></h2><p>For a one-time, immediate review, structured conversation evidence may be enough. Long-lived digital employees need another record when authority must survive across time, retries or delegated hops.</p><p>That durable state should bind at least:</p><ul><li>the authenticated principal represented by the authorization;</li><li>the exact action, resource or capability scope;</li><li>the decision&#39;s freshness, expiry and replay boundary;</li><li>the conditions under which later messages revoke or supersede it;</li><li>the executor and audit event that consumed the grant.</li></ul><p>The distinction is operational, not semantic. A review record should say which evidence the reviewer observed. An execution record should say what authority was actually granted. Combining both into a natural-language transcript makes revocation, expiry and conflict resolution dependent on model interpretation at precisely the point where deterministic governance matters most.</p><p>Low-risk workflows may choose lighter controls. The point is proportionality: a conversational “yes” can be convenient context, but a sensitive or durable action should not inherit authority merely because another agent repeated that “yes” convincingly.</p><h2 id="a-safer-admission-boundary-not-an-authorization-guarantee" tabindex="-1">A safer admission boundary, not an authorization guarantee <a class="header-anchor" href="#a-safer-admission-boundary-not-an-authorization-guarantee" aria-label="Permalink to &quot;A safer admission boundary, not an authorization guarantee&quot;">​</a></h2><p>The public evidence is one merged Codex implementation and its integration tests. It demonstrates bounded root-history extraction for MultiAgent V2 Guardian review, role anti-spoof rendering and isolation from the ordinary worker request. It does not establish cryptographic human identity, reusable capability tokens, coverage of every Codex approval path or end-to-end authorization safety.</p><p>Assistant final answers remain visible as untrusted context, and the Guardian still has to honor the role boundary. The structured history also depends on the integrity of the upstream conversation store. These are real limits, not footnotes to be converted into a stronger claim.</p><p>The practical test is therefore simple: after a delegated action completes, can the audit show both <strong>which authoritative evidence the reviewer saw</strong> and <strong>which scoped authority the executor received</strong>? If it can show only a persuasive transcript, provenance has already been lost.</p><p><strong>Primary evidence:</strong> <a href="https://github.com/openai/codex/commit/d12a7f3fd8a3f0dcffc665d515b9ee0dd3714315" target="_blank" rel="noreferrer">OpenAI Codex merged commit d12a7f3f</a>. The public code and tests support the bounded Guardian behavior described here; they are not independent validation of universal agent authorization safety.</p>',23))])}const y=a(d,[["render",c]]);export{g as __pageData,y as default};
